def list_all(fn, db):
    out, off = [], 0
    while True:
        r = fn(db=db, offset=off, limit=500)
        items = None
        for k in ('kinases','substrates','items','results','genes'):
            if isinstance(r, dict) and k in r: items = r[k]; break
        if items is None:
            print(str(r)[:500]); break
        out += items
        if len(items) < 500: break
        off += 500
    return out

